from __future__ import annotations

"""Top-level driver: run API calls under a retry budget and report on them.

This is what the worker layer uses. It owns the retry config and a sleeper, runs
each call through the executor, and rolls results up into the numbers the
on-call engineer watches when a rate-limit storm starts.
"""

import time
from dataclasses import dataclass, field
from typing import Callable

from backoff_executor import ExecutionResult, execute_with_retries
from request_client import ScriptedClient
from retry_policy import RetryConfig


def run_call(
    client: ScriptedClient,
    config: RetryConfig | None = None,
    sleeper: Callable[[float], None] = time.sleep,
) -> ExecutionResult:
    return execute_with_retries(client.as_operation(), config=config, sleeper=sleeper)


def summarize_runs(results: list[ExecutionResult]) -> dict[str, object]:
    return {
        "call_count": len(results),
        "succeeded": sum(1 for r in results if r.succeeded()),
        "failed": sum(1 for r in results if not r.succeeded()),
        "total_attempts": sum(r.attempts for r in results),
        "wasted_attempts": sum(r.wasted_attempts() for r in results),
        "total_wait_seconds": sum(r.total_sleep_seconds for r in results),
    }


@dataclass
class CallSession:
    """Stateful runner that remembers every call it has made."""

    config: RetryConfig = field(default_factory=RetryConfig)
    sleeper: Callable[[float], None] = time.sleep
    _history: list[ExecutionResult] = field(default_factory=list)

    def run(self, client: ScriptedClient) -> ExecutionResult:
        result = run_call(client, config=self.config, sleeper=self.sleeper)
        self._history.append(result)
        return result

    @property
    def history(self) -> list[ExecutionResult]:
        return list(self._history)

    def summary(self) -> dict[str, object]:
        return summarize_runs(self._history)

    def storm_score(self) -> int:
        """Total attempts spent on calls that never succeeded.

        A healthy session keeps this near zero; doomed requests retried in a
        loop are exactly what drives it up.
        """

        return sum(r.attempts for r in self._history if not r.succeeded())

    def total_wait_seconds(self) -> float:
        return sum(r.total_sleep_seconds for r in self._history)

    def failure_rate(self) -> float:
        if not self._history:
            return 0.0
        failed = sum(1 for r in self._history if not r.succeeded())
        return failed / len(self._history)

    def reset(self) -> None:
        self._history = []

    def latest(self) -> ExecutionResult | None:
        return self._history[-1] if self._history else None

    def call_count(self) -> int:
        return len(self._history)

