from __future__ import annotations

"""Normalized view of one OpenAI HTTP attempt and its rate-limit signals.

A 429 (or an overloaded 503) comes back with headers that tell you how long to
wait, e.g. ``retry-after: 7`` or the finer-grained ``retry-after-ms: 600``. A
hard client error (400 invalid request, 401 bad key, 404 unknown model) carries
no such promise — retrying it just burns quota. This module turns a raw attempt
into something the retry engine can reason about.
"""

from dataclasses import dataclass, field


def _lower_headers(headers: dict[str, str] | None) -> dict[str, str]:
    if not headers:
        return {}
    return {str(k).lower(): str(v) for k, v in headers.items()}


@dataclass(frozen=True)
class ApiOutcome:
    """One attempt at calling the API.

    ``status_code`` is ``None`` for transport failures (connection reset, read
    timeout) where no HTTP response ever arrived.
    """

    status_code: int | None
    headers: dict[str, str] = field(default_factory=dict)
    error_type: str | None = None
    body: dict | None = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "headers", _lower_headers(self.headers))

    def is_success(self) -> bool:
        return self.status_code is not None and 200 <= self.status_code < 300

    def is_transport_error(self) -> bool:
        return self.status_code is None

    def retry_after_seconds(self) -> float | None:
        """Seconds the server asked us to wait, if it said anything.

        ``retry-after-ms`` is the more precise signal and wins when both are
        present.
        """

        ms = self.headers.get("retry-after-ms")
        if ms is not None:
            try:
                return float(ms) / 1000.0
            except ValueError:
                pass
        seconds = self.headers.get("retry-after")
        if seconds is not None:
            try:
                return float(seconds)
            except ValueError:
                pass
        return None

    def category(self) -> str:
        if self.is_transport_error():
            return "transport_error"
        if self.is_success():
            return "success"
        if self.status_code == 429:
            return "rate_limited"
        if 500 <= self.status_code < 600:
            return "server_error"
        return "client_error"


def success(headers: dict[str, str] | None = None) -> ApiOutcome:
    return ApiOutcome(status_code=200, headers=headers or {})


def rate_limited(retry_after: float | None = None, retry_after_ms: int | None = None) -> ApiOutcome:
    headers: dict[str, str] = {}
    if retry_after is not None:
        headers["retry-after"] = str(retry_after)
    if retry_after_ms is not None:
        headers["retry-after-ms"] = str(retry_after_ms)
    return ApiOutcome(status_code=429, headers=headers, error_type="rate_limit_error")


def http_error(status_code: int, error_type: str | None = None) -> ApiOutcome:
    return ApiOutcome(status_code=status_code, error_type=error_type)


def transport_error(error_type: str = "connection_error") -> ApiOutcome:
    return ApiOutcome(status_code=None, error_type=error_type)

