from __future__ import annotations

"""A scripted stand-in for the OpenAI HTTP client.

Real calls are nondeterministic, so the executor is fed a client that replays a
fixed sequence of outcomes. This keeps retry behavior reproducible: the Nth
attempt always sees the Nth scripted outcome.
"""

from dataclasses import dataclass, field

from rate_limit_models import ApiOutcome


@dataclass(frozen=True)
class RequestSpec:
    """The call the client would have made."""

    model: str
    estimated_tokens: int

    def __post_init__(self) -> None:
        if not self.model.strip():
            raise ValueError("model is required")
        if self.estimated_tokens < 0:
            raise ValueError("estimated_tokens must be non-negative")


class ScriptedClient:
    """Replays a queued list of outcomes, one per attempt.

    If the queue runs dry, the final scripted outcome repeats. That mirrors a
    backend stuck returning the same error and lets a test prove the executor
    stops on its own rather than because the script ended.
    """

    def __init__(self, outcomes: list[ApiOutcome], spec: RequestSpec | None = None) -> None:
        if not outcomes:
            raise ValueError("at least one scripted outcome is required")
        self._outcomes = list(outcomes)
        self._spec = spec or RequestSpec(model="gpt-4o-mini", estimated_tokens=100)
        self._index = 0
        self._call_count = 0

    @property
    def call_count(self) -> int:
        return self._call_count

    @property
    def spec(self) -> RequestSpec:
        return self._spec

    def send(self) -> ApiOutcome:
        outcome = self._outcomes[min(self._index, len(self._outcomes) - 1)]
        self._index += 1
        self._call_count += 1
        return outcome

    def as_operation(self):
        """Return a zero-arg callable the executor can invoke each attempt."""

        return self.send

    def remaining_scripted(self) -> int:
        """How many distinct scripted outcomes have not been served yet."""

        return max(0, len(self._outcomes) - self._index)

    def reset(self) -> None:
        self._index = 0
        self._call_count = 0


@dataclass
class RecordingSleeper:
    """Stand-in for time.sleep that records what it was asked to wait."""

    waits: list[float] = field(default_factory=list)

    def __call__(self, seconds: float) -> None:
        self.waits.append(seconds)

    @property
    def total(self) -> float:
        return sum(self.waits)

