from __future__ import annotations

"""Decide whether and when to retry one failed attempt.

``plan_retry`` is the single decision point the executor consults after every
attempt. It looks at the outcome and the attempt count and returns a decision:
stop now, or wait this long and try again.
"""

from dataclasses import dataclass

from rate_limit_models import ApiOutcome


@dataclass(frozen=True)
class RetryConfig:
    max_attempts: int = 4
    base_delay_seconds: float = 0.5
    max_delay_seconds: float = 20.0

    def __post_init__(self) -> None:
        if self.max_attempts < 1:
            raise ValueError("max_attempts must be at least 1")
        if self.base_delay_seconds < 0:
            raise ValueError("base_delay_seconds must be non-negative")
        if self.max_delay_seconds < 0:
            raise ValueError("max_delay_seconds must be non-negative")


@dataclass(frozen=True)
class RetryDecision:
    should_retry: bool
    delay_seconds: float
    reason: str


def is_retryable(outcome: ApiOutcome) -> bool:
    """Whether an attempt is worth trying again."""

    if outcome.is_transport_error():
        return True
    return outcome.status_code >= 400


def compute_delay(outcome: ApiOutcome, attempt: int, config: RetryConfig) -> float:
    """How long to wait before the next attempt (seconds)."""

    backoff = config.base_delay_seconds * (2 ** attempt)
    return min(config.max_delay_seconds, backoff)


def plan_retry(outcome: ApiOutcome, attempt: int, config: RetryConfig) -> RetryDecision:
    """Decide the next move after attempt number ``attempt`` (0-based)."""

    if outcome.is_success():
        return RetryDecision(False, 0.0, "success")

    # Already used the last attempt we are allowed.
    if attempt + 1 >= config.max_attempts:
        return RetryDecision(False, 0.0, "max_attempts_exhausted")

    if not is_retryable(outcome):
        return RetryDecision(False, 0.0, "non_retryable")

    delay = compute_delay(outcome, attempt, config)
    return RetryDecision(True, delay, "retry")


def describe_decision(decision: RetryDecision) -> str:
    if not decision.should_retry:
        return f"stop ({decision.reason})"
    return f"retry after {decision.delay_seconds:.3f}s"


def plan_attempts(outcomes: list[ApiOutcome], config: RetryConfig) -> list[RetryDecision]:
    """Replay a sequence of outcomes through the policy for inspection.

    Useful for logging or tests that want to see what the policy *would* decide
    at each step without driving the executor.
    """

    decisions: list[RetryDecision] = []
    for attempt, outcome in enumerate(outcomes):
        decision = plan_retry(outcome, attempt, config)
        decisions.append(decision)
        if not decision.should_retry:
            break
    return decisions


def total_planned_wait(outcomes: list[ApiOutcome], config: RetryConfig) -> float:
    return sum(d.delay_seconds for d in plan_attempts(outcomes, config) if d.should_retry)

